 public function applicable():bool{$i=Common::installed();$c=Common::code();return($i['version']??'')==='2.2.0'&&(int)($i['schema_version']??0)===3&&($c['version']??'')==='2.3.0'&&(int)($c['schema_version']??0)===4&&is_file($this->baselineDir.'/baseline.json')&&is_file($this->baselineDir.'/rollback-files.zip')&&is_file($this->baselineDir.'/target-manifest.json')&&is_file($this->baselineDir.'/target-manifest.sig');}
 public function run(int|string|null $userId=null):array{
  if(!$this->applicable())throw new \RuntimeException('Overlay update is not applicable to this installed release.');$lock=@fopen($this->lock,'x');if(!$lock)throw new \RuntimeException('OVERLAY UPDATE ALREADY RUNNING');fwrite($lock,(string)getmypid());fclose($lock);
  $id=gmdate('YmdHis').'-overlay-'.bin2hex(random_bytes(4));$state=['id'=>$id,'state'=>'PREFLIGHT','from'=>'2.2.0','to'=>'2.3.0','started_at'=>gmdate('c')];$dbBackup=null;$baseline=[];
  try{$baseline=$this->loadBaseline();$this->verifyTargetManifest();$this->writeState($state);$state['state']='BACKUP';$dbBackup=(new BackupManager())->database($id);$state['database_backup']=$dbBackup;$state['database_backup_sha256']=hash_file('sha256',$dbBackup);$this->writeState($state);$state['state']='MIGRATIONS';$this->artisan(['migrate','--force']);$state['state']='CACHE';foreach([['config:clear'],['cache:clear'],['view:clear'],['route:clear']] as $a)$this->artisan($a,false);$state['state']='POSTFLIGHT';$this->postflight();if($this->postflightProbe!==null&&!($this->postflightProbe)($this->base,$state))throw new \RuntimeException('Overlay postflight probe rejected the candidate.');$this->promoteOverlayMfaCounters();$state['state']='ACTIVATE';$code=Common::code();$trustVersion=(int)((new TrustStore())->current()['version']??0);$installedNew=['version'=>(string)$code['version'],'schema_version'=>(int)$code['schema_version'],'release_id'=>$code['release_id']??null,'installed_at'=>gmdate('c'),'status'=>'INSTALLED','trust_store_version'=>$trustVersion,'signing_key_id'=>$code['release_signing_key_id']??null];file_put_contents($this->base.'/storage/app/private/installed-release.json',json_encode($installedNew,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),LOCK_EX);@chmod($this->base.'/storage/app/private/installed-release.json',0600);$this->recordVersion($installedNew);$state['state']='COMPLETE';$state['finished_at']=gmdate('c');$this->writeState($state);return$state;}
