 private function loadBaseline():array{$raw=(string)file_get_contents($this->baselineDir.'/baseline.json');$d=json_decode($raw,true);if(!is_array($d)||($d['format']??'')!=='bee-overlay-baseline/1')throw new \RuntimeException('Invalid overlay baseline metadata.');if(($d['from_version']??'')!=='2.2.0'||(int)($d['from_schema']??0)!==3||($d['to_version']??'')!=='2.3.0'||(int)($d['to_schema']??0)!==4)throw new \RuntimeException('Overlay baseline version mismatch.');$zip=$this->baselineDir.'/rollback-files.zip';$e=strtolower((string)($d['rollback_files_sha256']??''));if(!preg_match('/^[a-f0-9]{64}$/',$e)||!hash_equals($e,hash_file('sha256',$zip)))throw new \RuntimeException('Overlay rollback archive integrity failure.');return$d;}
