 private function postflight():void{foreach(['vendor/autoload.php','composer.lock','artisan','bootstrap/app.php','public/index.php','release.json','resources/keys/root-public.key']as$f)if(!is_file($this->base.'/'.$f))throw new \RuntimeException('Overlay postflight missing '.$f);$pdo=Common::pdo();$pdo->query('SELECT 1');if(!$pdo->query("SHOW COLUMNS FROM users LIKE 'mfa_last_timestep'")->fetch())throw new \RuntimeException('Overlay schema postflight failed: mfa_last_timestep missing.');$n=(int)$pdo->query("SELECT COUNT(*) FROM migrations WHERE migration='2026_10_30_000010_v23_session_mfa_hardening'")->fetchColumn();if($n!==1)throw new \RuntimeException('Overlay schema postflight failed: V2.3 migration not recorded.');(new TrustStore())->current();$this->verifyTargetManifest();}
 private function rollbackFiles(array$b):void{$late=[];foreach((array)($b['new_roots_to_remove']??[])as$r){$this->assertSafeRelativePath((string)$r);if(str_starts_with((string)$r,'resources/update-baselines')){$late[]=(string)$r;continue;}$this->removeTree($this->base.'/'.(string)$r);}foreach((array)($b['new_files_to_remove']??[])as$r){$this->assertSafeRelativePath((string)$r);if(str_starts_with((string)$r,'resources/update-baselines/'))continue;$p=$this->base.'/'.(string)$r;if(is_file($p)||is_link($p))@unlink($p);}(new RestoreManager())->restoreFiles($this->baselineDir.'/rollback-files.zip');foreach((array)($b['old_hashes']??[])as$r=>$e){$this->assertSafeRelativePath((string)$r);$p=$this->base.'/'.(string)$r;if(!is_file($p)||!hash_equals(strtolower((string)$e),hash_file('sha256',$p)))throw new \RuntimeException('Overlay rollback hash mismatch: '.$r);}foreach($late as$r)$this->removeTree($this->base.'/'.$r);}
 private function promoteOverlayMfaCounters():void{$p=$this->base.'/storage/app/private/overlay-mfa-state.json';if(!is_file($p))return;$d=json_decode((string)file_get_contents($p),true)?:[];$pdo=Common::pdo();foreach((array)($d['users']??[])as$id=>$c){$s=$pdo->prepare('UPDATE users SET mfa_last_timestep=GREATEST(COALESCE(mfa_last_timestep,0),?),updated_at=NOW() WHERE id=?');$s->execute([(int)$c,(string)$id]);}@unlink($p);}
 private function artisan(array$a,bool$req=true):void{$cmd=array_map('escapeshellarg',array_merge([PHP_BINARY,$this->base.'/artisan'],$a));exec(implode(' ',$cmd).' 2>&1',$o,$c);if($req&&$c!==0)throw new \RuntimeException('Artisan failed: '.implode("\n",$o));}
 private function recordVersion(array$i):void{try{$pdo=Common::pdo();$has=$pdo->query("SHOW COLUMNS FROM platform_versions LIKE 'trust_store_version'")->fetch();if($has){$s=$pdo->prepare('INSERT INTO platform_versions(version,schema_version,trust_store_version,release_id,installed_at,created_at,updated_at) VALUES(?,?,?,?,?,NOW(),NOW())');$s->execute([$i['version'],$i['schema_version'],$i['trust_store_version']??null,$i['release_id'],date('Y-m-d H:i:s')]);}else{$s=$pdo->prepare('INSERT INTO platform_versions(version,schema_version,release_id,installed_at,created_at,updated_at) VALUES(?,?,?,?,NOW(),NOW())');$s->execute([$i['version'],$i['schema_version'],$i['release_id'],date('Y-m-d H:i:s')]);}}catch(\Throwable){}}
